 1	import java.util.Arrays;
 2	import java.util.Objects;
 3	
 4	final class RadixSort {
 5	    private static final int RADIX = 10;
 6	
 7	    private RadixSort() {
 8	    }
 9	
10	    static void sort(int[] values) {
11	        validateInput(values);
12	        if (values.length < 2) {
13	            return;
14	        }
15	
16	        int maxValue = findMax(values);
17	        for (int exponent = 1; maxValue / exponent > 0; exponent *= RADIX) {
18	            countingSortByDigit(values, exponent);
19	        }
20	    }
21	
22	    private static void validateInput(int[] values) {
23	        Objects.requireNonNull(values, "values");
24	
25	        for (int value : values) {
26	            if (value < 0) {
27	                throw new IllegalArgumentException(
28	                    "Radix sort only supports non-negative integers."
29	                );
30	            }
31	        }
32	    }
33	
34	    private static int findMax(int[] values) {
35	        int maxValue = values[0];
36	        for (int index = 1; index < values.length; index++) {
37	            if (values[index] > maxValue) {
38	                maxValue = values[index];
39	            }
40	        }
41	        return maxValue;
42	    }
43	
44	    private static void countingSortByDigit(int[] values, int exponent) {
45	        int[] output = new int[values.length];
46	        int[] counts = new int[RADIX];
47	
48	        for (int value : values) {
49	            counts[digitAt(value, exponent)]++;
50	        }
51	
52	        for (int digit = 1; digit < RADIX; digit++) {
53	            counts[digit] += counts[digit - 1];
54	        }
55	
56	        for (int index = values.length - 1; index >= 0; index--) {
57	            int value = values[index];
58	            int digit = digitAt(value, exponent);
59	            output[--counts[digit]] = value;
60	        }
61	
62	        System.arraycopy(output, 0, values, 0, values.length);
63	    }
64	
65	    private static int digitAt(int value, int exponent) {
66	        return (value / exponent) % RADIX;
67	    }
68	
69	    static void print(int[] values) {
70	        System.out.println(Arrays.toString(values));
71	    }
72	
73	    public static void main(String[] args) {
74	        int[] values = {170, 45, 75, 90, 802, 24, 2, 66};
75	        sort(values);
76	        print(values);
77	    }
78	}
